function Salutation({ nom }) {
  return (
    <div style={{ padding: '16px', background: '#252836', borderRadius: '8px' }}>
      <h2>👋 Bonjour, {nom} !</h2>
      <p>Je suis un composant React.</p>
    </div>
  )
}

// On l'utilise comme une balise HTML
